argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$status=@(& $git -C $repo status --short);
$diffNames=@(& $git -C $repo diff --name-status);
$cached=@(& $git -C $repo diff --cached --name-status);
$head=((@(& $git -C $repo rev-parse HEAD))-join '').Trim();
[pscustomobject]@{head=$head;status=$status;diffNames=$diffNames;cached=$cached}|ConvertTo-Json -Depth 5 -Compress
